void Listener::doApply() {
  while (!isStopped()) {
    if (needToCleanupSnapshot()) {
      cleanupSnapshot();
    }
    // todo(doodle): only put is handled, all remove is ignored for now
    processLogs();
    sleep(FLAGS_listener_commit_interval_secs);
  }

nebula::cpp2::ErrorCode RebuildFTIndexTask::taskByPart(nebula::kvstore::Listener* listener) {
  auto part = listener->partitionId();
  listener->resetListener();
  while (true) {
    sleep(FLAGS_raft_heartbeat_interval_secs);
    if (listener->pursueLeaderDone()) {
      return nebula::cpp2::ErrorCode::SUCCEEDED;
    }
    VLOG(1) << folly::sformat("Processing fulltext rebuild subtask, part={}, rebuild_log={}",
                              part,
                              listener->getApplyId());
  }
  return nebula::cpp2::ErrorCode::SUCCEEDED;
}
